def feasible(self, low, need_cut=False):
    """True when a feasible circulation realises `low` on the flow arcs."""
    total = 0
    for l in low:
        total += l
    if total == 0:
        return True, None
    cap = self.aux_base[:]
    amap = self.aux_map
    supply = {}
    for f in range(self.F):
        l = low[f]
        ce = self.ceiling[f] - l
        cap[amap[self.flow_arc[f]]] = ce if ce > 0 else 0
        if l:
            h = self.fhead[f]
            supply[h] = supply.get(h, 0) + l
        cap[self.aux_tt[f]] = l
    for v, amt in supply.items():
        cap[self.aux_ss[v]] = amt
    g = self.aux_g
    val = GL.maxflow(self.aux_n, g.adj, g.to, cap, self.SS, self.TT,
                     limit=total)
    if val >= total:
        return True, None
    if not need_cut:
        return False, None
    seen = GL.reachable(self.aux_n, g.adj, g.to, cap, self.SS)
    return False, [v for v in range(self.K) if seen[v]]

def static_ok(self, low):
    """Necessary (and ceiling exact) conditions without the slot side."""
    total = 0
    for f in range(self.F):
        l = low[f]
        if l > self.ceiling[f]:
            return False
        total += l
